def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None

        # Parse in chunks so amounts are not subject to Python's
        # string-to-integer digit limit.
        value = 0
        for i in range(0, len(token), 9):
            chunk = token[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    def apply(parts):
        if not parts or any(part == "" for part in parts):
            return False

        verb = parts[0]

        if verb == "undo":
            if len(parts) != 1 or not history:
                return False

            entry = history.pop()
            action = entry[0]

            if action == "open":
                del balances[entry[1]]
                frozen.discard(entry[1])
            elif action == "deposit":
                balances[entry[1]] -= entry[2]
            elif action == "withdraw":
                balances[entry[1]] += entry[2]
            elif action == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif action == "freeze":
                frozen.remove(entry[1])
            else:
                frozen.add(entry[1])
            return True

        if verb in ("open", "deposit", "withdraw"):
            if len(parts) != 3:
                return False

            account = parts[1]
            amount = parse_amount(parts[2])
            if amount is None:
                return False

            if verb == "open":
                if account in balances:
                    return False
                balances[account] = amount
                history.append(("open", account))
            elif verb == "deposit":
                if amount == 0 or account not in balances:
                    return False
                balances[account] += amount
                history.append(("deposit", account, amount))
            else:
                if (
                    amount == 0
                    or account not in balances
                    or account in frozen
                    or balances[account] < amount
                ):
                    return False
                balances[account] -= amount
                history.append(("withdraw", account, amount))
            return True

        if verb == "transfer":
            if len(parts) != 4:
                return False

            source, destination = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount is None
                or amount == 0
                or source == destination
                or source not in balances
                or destination not in balances
                or source in frozen
                or balances[source] < amount
            ):
                return False

            balances[source] -= amount
            balances[destination] += amount
            history.append(("transfer", source, destination, amount))
            return True

        if verb in ("freeze", "unfreeze"):
            if len(parts) != 2:
                return False

            account = parts[1]
            if account not in balances:
                return False

            if verb == "freeze":
                if account in frozen:
                    return False
                frozen.add(account)
            else:
                if account not in frozen:
                    return False
                frozen.remove(account)

            history.append((verb, account))
            return True

        return False

    for index, operation in enumerate(ops):
        if not apply(operation.split(" ")):
            rejected.append(index)

    return balances, rejected
